func (t RealtimeEvent) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "account.balance_updated":
		return t.AsBalanceUpdatedEvent()
	case "ajo.updated":
		return t.AsAjoUpdatedEvent()
	case "card.authorization":
		return t.AsCardAuthorizationEvent()
	case "dispute.updated":
		return t.AsDisputeUpdatedEvent()
	case "family.approval_requested":
		return t.AsFamilyApprovalRequestedEvent()
	case "fx.alert_triggered":
		return t.AsFxAlertTriggeredEvent()
	case "kyc.updated":
		return t.AsKycUpdatedEvent()
	case "money_request.received":
		return t.AsMoneyRequestReceivedEvent()
	case "notification.created":
		return t.AsNotificationCreatedEvent()
	case "security.panic_changed":
		return t.AsSecurityPanicChangedEvent()
	case "session.revoked":
		return t.AsSessionRevokedEvent()
	case "statement.ready":
		return t.AsStatementReadyEvent()
	case "support.message":
		return t.AsSupportMessageEvent()
	case "support.typing":
		return t.AsSupportTypingEvent()
	case "transaction.created":
		return t.AsTransactionCreatedEvent()
	case "transfer.updated":
		return t.AsTransferUpdatedEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

