// WebhookReceiverInterface represents handlers for receiving inbound
// webhook requests. Each webhook becomes a Handle*Webhook
// method that the implementation fills in. The caller mounts the per-
// webhook gin.HandlerFunc returned by {Op}WebhookHandler at
// whatever URL path they advertise to senders.
type WebhookReceiverInterface interface {
	// account.credited
	// HandleOnAccountCreditedWebhook handles the POST webhook for account.credited.
	HandleOnAccountCreditedWebhook(c *gin.Context, params OnAccountCreditedParams)
	// payment_link.paid
	// HandleOnPaymentLinkPaidWebhook handles the POST webhook for payment_link.paid.
	HandleOnPaymentLinkPaidWebhook(c *gin.Context, params OnPaymentLinkPaidParams)
	// transfer.completed
	// HandleOnTransferCompletedWebhook handles the POST webhook for transfer.completed.
	HandleOnTransferCompletedWebhook(c *gin.Context, params OnTransferCompletedParams)
	// transfer.failed
	// HandleOnTransferFailedWebhook handles the POST webhook for transfer.failed.
	HandleOnTransferFailedWebhook(c *gin.Context, params OnTransferFailedParams)
	// transfer.reversed
	// HandleOnTransferReversedWebhook handles the POST webhook for transfer.reversed.
	HandleOnTransferReversedWebhook(c *gin.Context, params OnTransferReversedParams)
}

// OnAccountCreditedWebhookHandler returns the gin.HandlerFunc for the account.credited webhook.
